-- ============================================================
-- Driver CSV Migration Script
-- Source: Old system MongoDB export (approved drivers only)
-- Total approved drivers: 189
-- Generated: 2026-08-13 13:45:53 UTC
-- ============================================================

-- STEP 1: Create staging table
DROP TABLE IF EXISTS driver_csv_import;

CREATE TABLE driver_csv_import (
    id SERIAL PRIMARY KEY,
    old_id TEXT,
    name TEXT,
    email TEXT,
    phone TEXT,
    country_code TEXT,
    gender TEXT,
    license_number TEXT,
    device_type TEXT,
    referral_code TEXT,
    image TEXT,
    is_active BOOLEAN,
    is_approved BOOLEAN,
    is_block BOOLEAN,
    is_deleted BOOLEAN,
    latitude DOUBLE PRECISION,
    longitude DOUBLE PRECISION,
    timezone TEXT,
    old_created_at TIMESTAMPTZ,
    old_approved_on TIMESTAMPTZ,
    old_updated_at TIMESTAMPTZ,
    old_reject_on TIMESTAMPTZ,
    matched_driver_id UUID,  -- filled by STEP 3
    migration_status TEXT DEFAULT 'pending'  -- pending/matched/updated/skipped
);

-- STEP 2: Insert approved drivers from old CSV











-- STEP 3: Match imported drivers to existing drivers by phone number
UPDATE driver_csv_import di
SET matched_driver_id = u.id::uuid,
    migration_status = 'matched'
FROM users u
INNER JOIN drivers d ON d.user_id = u.id
WHERE u.phone = di.phone
  AND di.migration_status = 'pending';

-- STEP 3b: Try matching by email for any still-unmatched
UPDATE driver_csv_import di
SET matched_driver_id = u.id::uuid,
    migration_status = 'matched'
FROM users u
INNER JOIN drivers d ON d.user_id = u.id
WHERE u.email = di.email
  AND di.migration_status = 'pending'
  AND di.email IS NOT NULL;

-- STEP 4: Review matches before updating (RUN THIS FIRST)
-- Check matched count:
SELECT migration_status, COUNT(*) FROM driver_csv_import GROUP BY migration_status;

-- Preview matched drivers:
SELECT di.name, di.email, di.phone, di.old_created_at, di.old_approved_on,
       d.created_at AS current_created_at, d.verified_at AS current_verified_at,
       di.matched_driver_id
FROM driver_csv_import di
JOIN drivers d ON d.user_id = di.matched_driver_id
WHERE di.migration_status = 'matched'
ORDER BY di.old_created_at;

-- Preview unmatched drivers (these exist in old system but NOT in new):
SELECT di.name, di.email, di.phone, di.old_created_at, di.old_approved_on
FROM driver_csv_import di
WHERE di.migration_status = 'pending'
ORDER BY di.old_created_at;

-- ============================================================
-- STEP 5: Apply date updates to drivers table
-- !!! ONLY RUN AFTER REVIEWING STEP 4 OUTPUT !!!
-- ============================================================

-- Update created_at (original signup date from old system)
UPDATE drivers d
SET created_at = di.old_created_at
FROM driver_csv_import di
WHERE d.user_id = di.matched_driver_id
  AND di.migration_status = 'matched'
  AND di.old_created_at IS NOT NULL;

-- Update verified_at (approval date from old system)
UPDATE drivers d
SET verified_at = di.old_approved_on
FROM driver_csv_import di
WHERE d.user_id = di.matched_driver_id
  AND di.migration_status = 'matched'
  AND di.old_approved_on IS NOT NULL;

-- Update updated_at (last update from old system)
UPDATE drivers d
SET updated_at = di.old_updated_at
FROM driver_csv_import di
WHERE d.user_id = di.matched_driver_id
  AND di.migration_status = 'matched'
  AND di.old_updated_at IS NOT NULL;

-- Mark updated rows
UPDATE driver_csv_import
SET migration_status = 'updated'
WHERE migration_status = 'matched';

-- STEP 6: Final verification
SELECT migration_status, COUNT(*) FROM driver_csv_import GROUP BY migration_status;

SELECT d.user_id, di.name, di.phone,
       d.created_at, d.verified_at, d.updated_at
FROM drivers d
JOIN driver_csv_import di ON d.user_id = di.matched_driver_id
WHERE di.migration_status = 'updated'
ORDER BY d.created_at;

-- STEP 7: Cleanup (run when satisfied with migration)
